import { HbrTableNS } from "../../interfaces";
import { getItemByPosition } from "../dimension/dimension.helpers";

export type DimensionDataViewport = Pick<
	HbrTableNS.DimensionSettingsState,
	| "indexes"
	| "positionIndexes"
	| "positionIndexToItem"
	| "sizes"
	| "originItemSize"
	| "realSize"
	| "frameOffset"
>;

type ItemsToUpdate = Pick<
	HbrTableNS.ViewportStateItems,
	"items" | "start" | "end"
>;
/**
 * Update items based on new scroll position
 * If viewport wasn't changed fully simple recombination of positions
 * Otherwise rebuild viewport items
 */
export function getUpdatedItemsByPosition<T extends ItemsToUpdate>(
	pos: number,
	items: T,
	realCount: number,
	virtualSize: number,
	dimension: DimensionDataViewport,
): ItemsToUpdate {
	const activeItem: HbrTableNS.PositionItem = getItemByPosition(dimension, pos);
	const firstItem: HbrTableNS.VirtualPositionItem = getFirstItem(items);
	let toUpdate: ItemsToUpdate;

	// do simple position replacement if items already present in viewport
	if (firstItem) {
		const changedOffsetStart: number =
			activeItem.itemIndex - (firstItem.itemIndex || 0);
		if (changedOffsetStart) {
			// simple recombination
			const newData: ItemsToUpdate | null = recombineByOffset(
				Math.abs(changedOffsetStart),
				{
					positiveDirection: changedOffsetStart > -1,
					...dimension,
					...items,
				},
			);

			if (newData) {
				toUpdate = newData;
			}

			// if partial replacement add items if revo-viewport has some space left
			if (toUpdate) {
				const extra = addMissingItems(
					activeItem,
					realCount,
					virtualSize,
					toUpdate,
					dimension,
				);
				if (extra.length) {
					updateMissingAndRange(toUpdate.items, extra, toUpdate);
				}
			}
		}
	}

	// new collection if no items after replacement full replacement
	if (!toUpdate) {
		const items = getItems({
			start: activeItem.start,
			startIndex: activeItem.itemIndex,
			origSize: dimension.originItemSize,
			maxSize: virtualSize,
			maxCount: realCount,
			sizes: dimension.sizes,
		});

		// range now comes from 0 to length - 1
		toUpdate = {
			items,
			start: 0,
			end: items.length - 1,
		};
	}
	return toUpdate;
}

export function updateMissingAndRange(
	items: HbrTableNS.VirtualPositionItem[],
	missing: HbrTableNS.VirtualPositionItem[],
	range: HbrTableNS.Range,
) {
	items.splice(range.end + 1, 0, ...missing);
	// update range if start larger after recombination
	if (
		range.start >= range.end &&
		!(range.start === range.end && range.start === 0)
	) {
		range.start += missing.length;
	}
	range.end += missing.length;
}

// if partial replacement add items if revo-viewport has some space left
export function addMissingItems<T extends ItemsToUpdate>(
	firstItem: HbrTableNS.PositionItem,
	realCount: number,
	virtualSize: number,
	existingCollection: T,
	dimension: Pick<
		HbrTableNS.DimensionSettingsState,
		"sizes" | "originItemSize"
	>,
): HbrTableNS.VirtualPositionItem[] {
	const lastItem: HbrTableNS.VirtualPositionItem =
		getLastItem(existingCollection);
	const items = getItems({
		sizes: dimension.sizes,
		start: lastItem.end,
		startIndex: lastItem.itemIndex + 1,
		origSize: dimension.originItemSize,
		maxSize: virtualSize - (lastItem.end - firstItem.start),
		maxCount: realCount,
	});
	return items;
}

// get revo-viewport items parameters, caching position and calculating items count in revo-viewport
export function getItems(
	opt: {
		startIndex: number;
		start: number;
		origSize: number;
		maxSize: number;
		maxCount: number;
		sizes?: HbrTableNS.ViewSettingSizeProp;
	},
	currentSize = 0,
): HbrTableNS.VirtualPositionItem[] {
	const items: HbrTableNS.VirtualPositionItem[] = [];
	let index: number = opt.startIndex;
	let size: number = currentSize;
	while (size <= opt.maxSize && index < opt.maxCount) {
		const newSize: number = getItemSize(index, opt.sizes, opt.origSize);
		items.push({
			start: opt.start + size,
			end: opt.start + size + newSize,
			itemIndex: index,
			size: newSize,
		});
		size += newSize;
		index++;
	}
	return items;
}

/**
 * Do batch items recombination
 * If items not overlapped with existing viewport returns null
 */
export function recombineByOffset(
	offset: number,
	data: {
		positiveDirection: boolean;
	} & ItemsToUpdate &
		Pick<
			HbrTableNS.DimensionSettingsState,
			"sizes" | "realSize" | "originItemSize"
		>,
): ItemsToUpdate | null {
	const newItems = [...data.items];
	const itemsCount = newItems.length;
	const newRange = {
		start: data.start,
		end: data.end,
	};

	// if offset out of revo-viewport, makes sense whole redraw
	if (offset > itemsCount) {
		return null;
	}

	// is direction of scroll positive
	if (data.positiveDirection) {
		// push item to the end
		let lastItem: HbrTableNS.VirtualPositionItem = getLastItem(data);

		let i: number = newRange.start;
		const length = i + offset;
		for (; i < length; i++) {
			const newIndex: number = lastItem.itemIndex + 1;
			const size: number = getItemSize(
				newIndex,
				data.sizes,
				data.originItemSize,
			);

			// if item overlapped limit break a loop
			if (lastItem.end + size > data.realSize) {
				break;
			}

			// new item index to recombine
			const newEnd = i % itemsCount;

			// item should always present, we do not create new item, we recombine them
			if (!newItems[newEnd]) {
				throw new Error("incorrect index");
			}

			// do recombination
			newItems[newEnd] = lastItem = {
				start: lastItem.end,
				end: lastItem.end + size,
				itemIndex: newIndex,
				size: size,
			};
			// update range
			newRange.start++;
			newRange.end = newEnd;
		}

		// direction is negative
	} else {
		// push item to the start
		let firstItem: HbrTableNS.VirtualPositionItem = getFirstItem(data);

		const end = newRange.end;
		for (let i = 0; i < offset; i++) {
			const newIndex: number = firstItem.itemIndex - 1;
			const size: number = getItemSize(
				newIndex,
				data.sizes,
				data.originItemSize,
			);

			// new item index to recombine
			let newStart = end - i;
			newStart = (newStart < 0 ? itemsCount + newStart : newStart) % itemsCount;

			// item should always present, we do not create new item, we recombine them
			if (!newItems[newStart]) {
				throw new Error("incorrect index");
			}

			// do recombination
			newItems[newStart] = firstItem = {
				start: firstItem.start - size,
				end: firstItem.start,
				itemIndex: newIndex,
				size: size,
			};
			// update range
			newRange.start = newStart;
			newRange.end--;
		}
	}
	const range = {
		start:
			(newRange.start < 0 ? itemsCount + newRange.start : newRange.start) %
			itemsCount,
		end:
			(newRange.end < 0 ? itemsCount + newRange.end : newRange.end) %
			itemsCount,
	};
	return {
		items: newItems,
		...range,
	};
}

function getItemSize(
	index: number,
	sizes?: HbrTableNS.ViewSettingSizeProp,
	origSize = 0,
): number {
	if (sizes?.[index]) {
		return sizes[index];
	}
	return origSize;
}

/**
 * Verify if position is in range of the PositionItem, start and end are included
 */
export function isActiveRange(
	pos: number,
	realSize: number,
	first?: HbrTableNS.PositionItem,
	last?: HbrTableNS.PositionItem,
): boolean {
	if (!first || !last) {
		return false;
	}
	// if position is in range of first item
	// or position is after first item and last item is the last item in real size
	return (
		(pos >= first.start && pos <= first.end) ||
		(pos > first.end && last.end === realSize)
	);
}

export function getFirstItem(
	s: ItemsToUpdate,
): HbrTableNS.VirtualPositionItem | undefined {
	return s.items[s.start];
}

export function getLastItem(s: ItemsToUpdate): HbrTableNS.VirtualPositionItem {
	return s.items[s.end];
}

export function isActiveRangeOutsideLastItem(
	pos: number,
	virtualSize: number,
	firstItem?: HbrTableNS.PositionItem,
	lastItem?: HbrTableNS.PositionItem,
) {
	// if no first item, means no items in viewport
	if (!firstItem) {
		return false;
	}
	return virtualSize + pos > lastItem?.end;
}

/**
 * Set items sizes from start index to end
 * @param vpItems
 * @param start
 * @param size
 * @param lastCoordinate
 * @returns
 */
export function setItemSizes(
	vpItems: HbrTableNS.VirtualPositionItem[],
	initialIndex: number,
	size: number,
	lastCoordinate: number,
) {
	const items = [...vpItems];
	const count = items.length;

	let pos = lastCoordinate;
	let i = 0;
	let start = initialIndex;

	// viewport not inited
	if (!count) {
		return [];
	}
	// loop through array from initial item after recombination
	while (i < count) {
		const item = items[start];
		item.start = pos;
		item.size = size;
		item.end = item.start + size;
		pos = item.end;
		// loop by start index
		start++;
		i++;

		// if start index out of array, reset it
		if (start === count) {
			start = 0;
		}
	}
	return items;
}
