import { VNode, h } from "@stencil/core";
import { HbrTableNS } from "../../table-sub/interfaces";
import { DimensionStores } from "../../table-sub/services/dimension.provider";
import { ViewportStores } from "../../table-sub/services/viewport.provider";
import OrderRenderer, { OrdererService } from "../table-order/orderRenderer";

export interface ElementScroll {
	changeScroll?(
		e: HbrTableNS.ViewPortScrollEvent,
	): Promise<HbrTableNS.ViewPortScrollEvent>;
	setScroll(e: HbrTableNS.ViewPortScrollEvent): Promise<void>;
}

type Props = {
	viewports: ViewportStores;
	dimensions: DimensionStores;
	orderRef(e: OrdererService): void;
	registerElement(el: ElementScroll | null, key: string): void;
	onScroll(
		e: HbrTableNS.ViewPortScrollEvent,
		key?: HbrTableNS.DimensionColPin | string,
	): void;
	nakedClick(e: MouseEvent): void;
	tbSelf: any;
	viewPortUUID: string;
};

export const HbrViewPort = (
	{
		viewports,
		dimensions,
		orderRef,
		nakedClick,
		registerElement,
		onScroll,
		tbSelf,
		viewPortUUID,
	}: Props,
	children: VNode[],
) => {
	const viewPortClick = (e: MouseEvent, el?: HTMLElement) => {
		if (el === e.target) {
			nakedClick(e);
		}
	};

	let el: HTMLElement;
	return [
		<div
			class="main-viewport"
			ref={(e) => (el = e)}
			onClick={(e) => viewPortClick(e, el)}
			view-port-uuid={viewPortUUID}
		>
			<div class="viewports">
				{children}
				{tbSelf.pagination ? null : (
					<hbr-scroll-virtual
						class="vertical"
						dimension="rgRow"
						viewportStore={viewports.rgRow.store}
						dimensionStore={dimensions.rgRow.store}
						ref={(el) => registerElement(el, "rowScroll")}
						onScrollVirtual={(e) => onScroll(e.detail)}
					/>
				)}
				<OrderRenderer ref={orderRef} />
			</div>
		</div>,
		<hbr-scroll-virtual
			class="horizontal"
			dimension="rgCol"
			viewportStore={viewports.rgCol.store}
			dimensionStore={dimensions.rgCol.store}
			ref={(el) => registerElement(el, "colScroll")}
			onScrollVirtual={(e) => onScroll(e.detail)}
		/>,
	];
};
