/**
 * Storing pre-calculated
 * Dimension information and sizes
 */

import { createStore } from "@stencil/store";
import { reduce } from "../../../utils/function-helper";
import { HbrTableNS, Observable } from "../../interfaces";
import { setStore } from "../../utils/store.utils";
import { DimensionSize, calculateDimensionData } from "./dimension.helpers";

type Item = keyof HbrTableNS.DimensionSettingsState;

function initialBase(): HbrTableNS.DimensionCalc {
  return {
    indexes: [],
    // item index to size
    sizes: {},
    // order in indexes[] to coordinate
    positionIndexToItem: {},
    // initial element to coordinate ^
    indexToItem: {},
    positionIndexes: [],
  };
}

function initialState(): HbrTableNS.DimensionSettingsState {
  return {
    ...initialBase(),
    // size which all items can take
    realSize: 0,

    // initial item size if it wasn't changed
    originItemSize: 0,
    frameOffset: 0,
  };
}

export default class DimensionStore {
  readonly store: Observable<HbrTableNS.DimensionSettingsState>;
  constructor() {
    this.store = createStore(initialState());
  }

  getCurrentState(): HbrTableNS.DimensionSettingsState {
    const state = initialState();
    const keys: Item[] = Object.keys(state) as Item[];
    return reduce(
      keys,
      (r: HbrTableNS.DimensionSettingsState, k: Item) => {
        const data = this.store.get(k);
        r[k] = data as never;
        return r;
      },
      state
    );
  }

  setRealSize(count: number, tbSelf?: any): void {
    let realSize = 0;
    for (let i = 0; i < count; i++) {
      realSize +=
        this.store.get("sizes")[i] || this.store.get("originItemSize");
    }
    if (tbSelf?.pagination) {
      realSize = tbSelf?.paginationPlugin.getRealSize(count);
      setStore(this.store, { realSize });
    } else {
      setStore(this.store, { realSize });
    }
  }

  setStore<T extends { [key: string]: any }>(data: Partial<T>) {
    setStore(this.store, data);
  }

  drop() {
    setStore(this.store, initialBase());
  }

  setDimensionSize(sizes: HbrTableNS.ViewSettingSizeProp) {
    const dimensionData: DimensionSize = calculateDimensionData(
      this.getCurrentState(),
      sizes
    );
    setStore(this.store, dimensionData);
    return dimensionData;
  }
}
