import { HbrTableNS } from "../../table-sub/interfaces";

export interface ElementScroll {
	changeScroll?(
		e: HbrTableNS.ViewPortScrollEvent,
	): Promise<HbrTableNS.ViewPortScrollEvent>;
	setScroll(e: HbrTableNS.ViewPortScrollEvent): Promise<void>;
}
export type ElementsScroll = { [key: string]: ElementScroll[] };
export default class GridScrollingService {
	private elements: ElementsScroll = {};
	constructor(
		private setViewport: (e: HbrTableNS.ViewPortScrollEvent) => void,
	) {}

	async onScroll(
		e: HbrTableNS.ViewPortScrollEvent,
		key?: HbrTableNS.DimensionColPin | string,
	): Promise<void> {
		let newEvent: Promise<HbrTableNS.ViewPortScrollEvent>;
		for (const elKey in this.elements) {
			if (this.isPinnedColumn(key) && e.dimension === "rgCol") {
				if (elKey === key || !e.delta) {
					continue;
				}
				for (const el of this.elements[elKey]) {
					el.changeScroll && (newEvent = el.changeScroll(e));
				}
			} else {
				for (const el of this.elements[elKey]) {
					el.setScroll(e);
				}
			}
		}
		let event = e;
		if (newEvent) {
			event = await newEvent;
		}
		this.setViewport(event);
	}

	private isPinnedColumn(
		key?: HbrTableNS.DimensionColPin | string,
	): key is HbrTableNS.DimensionColPin {
		return ["colPinStart", "colPinEnd"].indexOf(key) > -1;
	}

	registerElements(els: ElementsScroll): void {
		this.elements = els;
	}

	/**
	 * Register new element for farther scroll support
	 * @param el - can be null if holder removed
	 * @param key - element key
	 */
	registerElement(el: ElementScroll | null, key: string): void {
		if (!this.elements[key]) {
			this.elements[key] = [];
		}
		// new element added
		if (el) {
			this.elements[key].push(el);
		} else if (this.elements[key]) {
			// element removed
			delete this.elements[key];
		}
	}

	unregister(): void {
		this.elements = undefined;
		this.elements = {};
	}
}
