import { HbrTableNS } from "../interfaces";

export const rowTypes: HbrTableNS.DimensionRows[] = [
	"rowPinStart",
	"rgRow",
	"rowPinEnd",
];
export const columnTypes: HbrTableNS.DimensionCols[] = [
	"colPinStart",
	"rgCol",
	"colPinEnd",
];

export function isRowType(
	type: HbrTableNS.DimensionRows | any,
): type is HbrTableNS.DimensionRows {
	return rowTypes.indexOf(type) > -1;
}
