import { type VNode, h } from "@stencil/core";
import { dotsSix } from "../../../icons";
import type { HbrTableNS, Selection } from "../../table-sub/interfaces";
import getBootstrapConfig from "../../utils/getBootstrapConfig";

type Props = { ref: (e: OrdererService) => void };

/**
 * Draw drag
 */
export class OrdererService {
	private parentY = 0;
	el!: HTMLElement;
	rgRow!: HTMLElement;
	text!: HTMLElement;
	draggable!: HTMLElement;

	start(
		parent: HTMLElement,
		{
			pos,
			text,
			event,
		}: { pos: HbrTableNS.PositionItem; text: string; event: MouseEvent },
	): void {
		const { top } = parent.getBoundingClientRect();
		this.parentY = top;
		if (this.text) {
			if (text) {
				this.text.innerText = text;
			} else {
				const ele = event.target as HTMLElement;
				const rowEle = ele.closest(".rgRow") as HTMLElement;
				if (rowEle) {
					const cloneRowEle = rowEle.cloneNode(true) as HTMLElement;
					const icon = cloneRowEle?.querySelector(".hbr-css__table-row-drag-button hbr-icon") as HTMLHbrIconElement;
					if (icon) {
						const customSystemIcons = getBootstrapConfig()?.systemIcons;
						icon.asset = customSystemIcons?.["dots-six"] || dotsSix
					}
					this.text.innerHTML = "";
					this.text.appendChild(cloneRowEle);
				}
			}
		}
		this.move(pos);
		this.moveTip({ x: event.x, y: event.y });
		this.el?.classList.remove("hidden");
	}
	end(): void {
		this.el?.classList.add("hidden");
	}
	move(pos: HbrTableNS.PositionItem): void {
		this.moveElement(pos.end - this.parentY);
	}
	moveTip({ x, y }: Selection.Cell): void {
		if (!this.draggable) {
			return;
		}
		this.draggable.style.left = `${x}px`;
		this.draggable.style.top = `${y}px`;
	}

	private moveElement(y: number): void {
		if (!this.rgRow) {
			return;
		}
		this.rgRow.style.transform = `translateY(${y}px)`;
	}
}

const OrderRenderer = ({ ref }: Props): VNode[] => {
	const customSystemIcons = getBootstrapConfig()?.systemIcons;
	const service = new OrdererService();
	ref(service);
	return (
		<div
			class="draggable-wrapper hidden"
			ref={(e) => {
				service.el = e;
			}}
		>
			<div
				class="draggable"
				ref={(el) => {
					service.draggable = el;
				}}
			>
				<hbr-icon asset={customSystemIcons?.["dots-six"] || dotsSix} />
				<span
					ref={(e) => {
						service.text = e;
					}}
				/>
			</div>
			<div
				class="drag-position"
				ref={(e) => {
					service.rgRow = e;
				}}
			/>
		</div>
	);
};
export default OrderRenderer;
