import { h } from "@stencil/core";
import BasePlugin from "../basePlugin";

export default class PaginationPlugin extends BasePlugin {
	paginationRef: HTMLHbrPaginationElement;
	constructor(protected tbSelf: any) {
		super(tbSelf.element);
		this.handlePageChanged = this.handlePageChanged.bind(this);
		this.changePageNumber = this.changePageNumber.bind(this);
		this.hanleScrollPostion = this.hanleScrollPostion.bind(this);

		//@ts-ignore
		this.addEventListener("hbr-page-changed", this.handlePageChanged);
		this.addEventListener("hbr-size-changed", this.handlePageChanged);
		tbSelf.element.addEventListener(
			"afterFilterApply",
			this.hanleScrollPostion,
		);
		if (tbSelf.subscribers && typeof tbSelf.subscribers === "object") {
			tbSelf.subscribers["hbr-page-changed"] = this.handlePageChanged;
			tbSelf.subscribers["hbr-size-changed"] = this.handlePageChanged;
		}

		this.tbSelf.element.registerVNode([
			<hbr-pagination
				// @ts-ignore
				uuid={`pagination-${tbSelf.uuid}`}
				page={tbSelf?.pagination?.page || 0}
				page-size={tbSelf?.pagination?.pageSize || 10}
				item-count={tbSelf?.source?.length || 0}
				ref={(r) => (this.paginationRef = r)}
			/>,
		]);

		setTimeout(() => {
			if (tbSelf.pagination?.page) {
				const pageSize: number = tbSelf?.pagination?.pageSize || 10;
				const page: number = tbSelf?.pagination?.page;
				this.tbSelf.scrollToRow(page * pageSize);
			}
		}, 500);
	}

	destroy() {
		this.tbSelf.element.removeEventListener(
			"afterFilterApply",
			this.hanleScrollPostion,
		);
	}

	changePageNumber(e: any) {
		this.clearSelection();
		const rowSize: number = this.tbSelf?.themeService?.rowSize || 0;
		const pageSize: number = this.tbSelf?.pagination?.pageSize || 10;
		let currentPage = e.detail.coordinate / rowSize / pageSize;
		currentPage = Math.floor(currentPage);
		currentPage = currentPage < 0 ? 0 : currentPage;
		if (this.paginationRef) {
			this.paginationRef.page = currentPage;
		}
	}

	hanleScrollPostion() {
		this.tbSelf.scrollToRow(0);
	}

	handlePageChanged(e: CustomEvent): void {
		this.clearSelection();
		const target =
			(e?.target as HTMLHbrPaginationElement) || this.paginationRef;
		const pageSize: number = target?.pageSize || 0;
		let page: number = e?.detail || 0;
		if (typeof this.tbSelf.pagination?.page === "number") {
			this.tbSelf.pagination.page = page;
		}
		if (typeof this.tbSelf.pagination?.pageSize === "number") {
			this.tbSelf.pagination.pageSize = pageSize;
		}
		if (typeof e?.detail !== "number" || !Number.isInteger(page)) page = 0;
		this.tbSelf.scrollToRow(page * pageSize);
		this.tbSelf.element.refresh();
	}

	clearSelection() {
		this.tbSelf?.selectionStoreConnector?.clearAll();
		this.tbSelf?.selectionStoreConnector?.setEdit(false);
		this.tbSelf?.viewport?.clearFocused();
	}

	rePagination() {
		this.clearSelection();
		const filteredItems =
			this.tbSelf.dataProvider.stores.rgRow.store.get("items");
		if (filteredItems) {
			this.paginationRef.itemCount = filteredItems.length;
			this.paginationRef.page = 0;
		}
	}

	getPageSize() {
		return (
			this.paginationRef?.pageSize || this.tbSelf.pagination?.pageSize || 10
		);
	}

	getRowSize() {
		return this.tbSelf?.themeService?.rowSize || 42;
	}

	getRealSize(count: number) {
		const height = this.getVerticalInnerHeight();
		let realSize = 0;
		const pageSize = this.getPageSize();
		const rowSize = this.getRowSize();
		const totalPage = Math.ceil(count / pageSize);
		realSize = rowSize * pageSize * totalPage;
		if (height) {
			const totalInnerHeight = totalPage * height;
			if (totalInnerHeight > realSize) {
				realSize = totalInnerHeight;
			}
		}
		return realSize;
	}

	canSelectOrEditPagination(cell: any): boolean {
		const pageSize = this.paginationRef?.pageSize;
		const page = this.paginationRef?.page + 1;
		const yStart = pageSize * page - pageSize;
		const yEnd = pageSize * page;
		if (!cell || (cell && cell.y < yStart) || (cell && cell.y >= yEnd))
			return true;
		return false;
	}

	getRows(rows: Array<any>) {
		const items = this.tbSelf.dataProvider.stores.rgRow.dataStore.get("items");
		const pageSize = this.getPageSize();
		const page = this.paginationRef?.page;
		return rows.filter(({ itemIndex }) => {
			const start = pageSize * page;
			const end = start + pageSize;
			return start <= itemIndex && itemIndex < end && itemIndex < items.length;
		});
	}

	getVerticalInnerHeight() {
		const innerElement = this.tbSelf.element.querySelector(".vertical-inner");
		const height = innerElement?.getBoundingClientRect()?.height;
		return height;
	}

	getLastPageHeight() {
		const items = this.tbSelf.dataProvider.stores.rgRow.dataStore.get("items");
		return (items.length % this.getPageSize()) * this.getRowSize();
	}

	isStopScrolling() {
		const height = this.getVerticalInnerHeight();
		const lastPageHeight = this.getLastPageHeight();
		const isLastPage = this.isLastPage();
		return height && isLastPage && lastPageHeight && lastPageHeight < height;
	}

	isLastPage() {
		const pageSize = this.getPageSize();
		const itemCount = this.paginationRef.itemCount;
		const refLastPage = Math.ceil(itemCount / pageSize);
		return this.paginationRef.page + 1 === refLastPage;
	}
}
