import { VNode, h } from "@stencil/core";
import { Edition, HbrTableNS } from "../../table-sub/interfaces";
import { UUID } from "../../table-sub/utils/consts";
import { ElementScroll } from "./viewport";
import { DATA_SLOT, HEADER_SLOT } from "./viewport.helpers";
import { ViewportProps } from "./viewport.interfaces";
type Props = {
	editors: Edition.Editors;
	useClipboard: boolean;
	readonly: boolean;
	range: boolean;
	rowClass: string;
	resize: boolean;
	columns: ViewportProps[];
	columnFilter: boolean;
	onScroll(
		e: HbrTableNS.ViewPortScrollEvent,
		key?: HbrTableNS.DimensionColPin | string,
	): void;
	onEdit(edit: Edition.BeforeEdit): void;
	tbSelf: any;
	registerElement(el: ElementScroll | null, key: string): void;
};
/**
 * All render based on sections
 * First we render vertical parts - pinned start, data, pinned end
 * Per each column we render data collections: headers, pinned top, center data, pinned bottom
 */
export const ViewPortSections = ({
	resize,
	editors,
	rowClass,
	readonly,
	range,
	columns,
	useClipboard,
	columnFilter,
	registerElement,
	onEdit,
	onScroll,
	tbSelf,
}: Props) => {
	const viewPortHtml: VNode[] = [];
	/** render viewports columns */
	for (const view of columns) {
		/** render viewports rows */

		const dataViews: HTMLElement[] = [
			<hbr-table-header
				viewportCol={view.viewportCol}
				{...view.headerProp}
				selectionStore={view.columnSelectionStore}
				slot={HEADER_SLOT}
				columnFilter={columnFilter}
				canResize={resize}
				tbSelf={tbSelf}
				role="rowgroup"
			/>,
		];
		view.dataPorts.forEach((data, j) => {
			const key = view.prop.key + (j + 1);

			const dataView = (
				<hbr-overlay-selection
					{...data}
					slot={data.slot}
					selectionStore={data.segmentSelectionStore}
					editors={editors}
					readonly={readonly}
					range={range}
					useClipboard={useClipboard}
					onSetEdit={({ detail }) => onEdit(detail)}
				>
					<hbr-table-data
						{...data}
						{...{ [UUID]: data.uuid }}
						key={key}
						readonly={readonly}
						range={range}
						rowClass={rowClass}
						rowSelectionStore={data.rowSelectionStore}
						slot={DATA_SLOT}
						tbSelf={tbSelf}
						data-table-uuid={tbSelf.uuid}
						role="rowgroup"
					/>
					<hbr-temp-range
						selectionStore={data.segmentSelectionStore}
						dimensionRow={data.dimensionRow}
						dimensionCol={data.dimensionCol}
					/>
					<hbr-focus
						selectionStore={data.segmentSelectionStore}
						dimensionRow={data.dimensionRow}
						dimensionCol={data.dimensionCol}
					/>
				</hbr-overlay-selection>
			);
			dataViews.push(dataView);
		});
		viewPortHtml.push(
			<hbr-viewport-scroll
				{...view.prop}
				tbSelf={view.tbSelf}
				ref={(el) => registerElement(el, view.prop.key)}
				onScrollViewport={(e) => onScroll(e.detail, view.prop.key)}
			>
				{dataViews}
			</hbr-viewport-scroll>,
		);
	}
	return viewPortHtml;
};
