import { size } from "../../../utils/function-helper";
import { HbrTableNS } from "../../interfaces";
import ColumnDataProvider from "../../services/column.data.provider";
import { setStore } from "../../utils/store.utils";
import BasePlugin from "../basePlugin";

import DimensionRows = HbrTableNS.DimensionRows;

export type SortingOrder = Record<HbrTableNS.ColumnProp, HbrTableNS.Order>;
type SortingOrderFunction = Record<
  HbrTableNS.ColumnProp,
  HbrTableNS.CellCompareFunc
>;
type SourceSetEvent = {
  type: DimensionRows;
  source: HbrTableNS.DataType[];
};
type ColumnSetEvent = {
  order: SortingOrder;
};

/**
 * lifecycle
 * 1) @event beforesorting - sorting just started, nothing happened yet
 * 2) @metod updateColumnSorting - column sorting icon applied to grid and column get updated, data still untiuched
 * 3) @event beforesortingapply - before we applied sorting data to data source, you can prevent data apply from here
 * 4) @event afterSortingApply - sorting applied, just finished event
 *
 * If you prevent event it'll not reach farther steps
 */

export default class SortingPlugin extends BasePlugin {
  private sorting: SortingOrder | null = null;
  private sortingFunc: SortingOrderFunction | null = null;
  // @ts-ignore
  private handleSorting: any;
  get name() {
    return "internalSorting";
  }

  get hasSorting() {
    return !!this.sorting;
  }

  constructor(protected revogrid: HTMLHbrTableElement) {
    super(revogrid);
    this.handleSorting = this.updateColumnSorting.bind(this);

    const beforesourceset = ({ detail }: CustomEvent<SourceSetEvent>) => {
      if (this.hasSorting) {
        // is sorting allowed
        const event = this.emit("beforesourcesortingapply");
        // sorting prevented
        if (event.defaultPrevented) {
          return;
        }
      }
      const data = this.setData(detail.source, detail.type);
      if (data) {
        detail.source = data;
      }
    };
    const aftercolumnsset = async ({
      detail: { order },
    }: CustomEvent<ColumnSetEvent>) => {
      const beforeEvent = this.emit("beforecolumnsordersort", {
        detail: { order },
      });
      if (beforeEvent.defaultPrevented) {
        return;
      }
      const columns = await this.revogrid.getColumns();
      const sortingFunc: SortingOrderFunction = {};

      for (const prop in order) {
        const column = ColumnDataProvider.getColumnByProp(columns, prop);
        const cmp: HbrTableNS.CellCompareFunc =
          column?.cellCompare || this.defaultCellCompare;

        sortingFunc[prop] =
          order[prop] === "desc" ? this.descCellCompare(cmp) : cmp;
      }
      this.sort(order, sortingFunc);
    };
    const headerclick = async (
      e: CustomEvent<HbrTableNS.InitialHeaderClick>
    ) => {
      if (e.defaultPrevented) {
        return;
      }

      if (!e.detail.column.sortable) {
        return;
      }

      this.headerclick(e.detail.column, e.detail.index);
    };

    this.addEventListener("beforesourceset", beforesourceset);
    this.addEventListener("aftercolumnsset", aftercolumnsset);
    this.addEventListener("initialHeaderClick", headerclick);
  }

  private async updateColumnSorting(
    column: HbrTableNS.ColumnRegular,
    index: number,
    order
  ) {
    const beforeEvent = this.emit("beforesorting", { column, order });
    if (beforeEvent.defaultPrevented) {
      return;
    }
    order = beforeEvent.detail.order;
    const newCol = await this.revogrid.updateColumnSorting(
      beforeEvent.detail.column,
      index,
      order
    );

    // apply sort data
    const beforeApplyEvent = this.emit("beforesortingapply", {
      column: newCol,
      order,
    });
    if (beforeApplyEvent.defaultPrevented) {
      return;
    }
    order = beforeApplyEvent.detail.order;

    const cmp: HbrTableNS.CellCompareFunc =
      column?.cellCompare || this.defaultCellCompare;

    this.sort(
      { [column.prop]: order },
      { [column.prop]: order === "desc" ? this.descCellCompare(cmp) : cmp }
    );
    return newCol;
  }

  private async headerclick(column: HbrTableNS.ColumnRegular, index: number) {
    let order: HbrTableNS.Order = this.getNextOrder(column.order);
    const beforeEvent = this.emit("beforesorting", { column, order });
    if (beforeEvent.defaultPrevented) {
      return;
    }
    order = beforeEvent.detail.order;
    const newCol = await this.revogrid.updateColumnSorting(
      beforeEvent.detail.column,
      index,
      order
    );

    // apply sort data
    const beforeApplyEvent = this.emit("beforesortingapply", {
      column: newCol,
      order,
    });
    if (beforeApplyEvent.defaultPrevented) {
      return;
    }
    order = beforeApplyEvent.detail.order;

    const cmp: HbrTableNS.CellCompareFunc =
      column?.cellCompare || this.defaultCellCompare;

    this.sort(
      { [column.prop]: order },
      { [column.prop]: order === "desc" ? this.descCellCompare(cmp) : cmp }
    );
  }

  private setData(
    data: HbrTableNS.DataType[],
    type: DimensionRows
  ): HbrTableNS.DataType[] | void {
    // sorting available for rgRow type only
    if (type === "rgRow" && this.sorting && this.sortingFunc) {
      return this.sortItems(data, this.sorting, this.sortingFunc);
    }
  }

  /**
   * Sorting apply, available for rgRow type only
   * @param sorting - per column sorting
   * @param data - this.stores['rgRow'].store.get('source')
   */
  private async sort(sorting: SortingOrder, sortingFunc: SortingOrderFunction) {
    if (!size(sorting)) {
      this.sorting = null;
      this.sortingFunc = null;
      return;
    }
    this.sorting = sorting;
    this.sortingFunc = sortingFunc;

    const store = await this.revogrid.getSourceStore();

    const source = store.get("source");
    const proxyItems = this.sortIndexByItems(
      [...store.get("proxyItems")],
      source,
      this.sorting,
      this.sortingFunc
    );
    setStore(store, {
      proxyItems,
      source: [...source],
    });
    this.emit("afterSortingApply");
  }

  private defaultCellCompare(
    prop: HbrTableNS.ColumnProp,
    a: HbrTableNS.DataType,
    b: HbrTableNS.DataType
  ) {
    const av = a[prop];
    const bv = b[prop];

    return av?.toString().toLowerCase() > bv?.toString().toLowerCase() ? 1 : -1;
  }

  private descCellCompare(cmp: HbrTableNS.CellCompareFunc) {
    return (
      prop: HbrTableNS.ColumnProp,
      a: HbrTableNS.DataType,
      b: HbrTableNS.DataType,
      dir: string
    ): number => {
      return -1 * cmp(prop, a, b, dir);
    };
  }

  private sortIndexByItems(
    indexes: number[],
    source: HbrTableNS.DataType[],
    sorting: SortingOrder,
    sortingFunc: SortingOrderFunction
  ): number[] {
    // TODO - is there a situation where multiple kvps in the `sorting` object would cause this to break?
    for (const prop in sortingFunc) {
      if (typeof sortingFunc[prop] === "undefined") {
        // Unsort indexes
        return [...Array(indexes.length).keys()];
      }
    }
    return indexes.sort((a, b) => {
      let sorted = 0;
      for (const prop in sortingFunc) {
        const dir = sorting[prop];
        const cmp = sortingFunc[prop];
        const itemA = source[a];
        const itemB = source[b];
        sorted = cmp(prop, itemA, itemB, dir);
        if (sorted) {
          break;
        }
      }
      return sorted;
    });
  }

  private sortItems(
    source: HbrTableNS.DataType[],
    sorting: SortingOrder,
    sortingFunc: SortingOrderFunction
  ): HbrTableNS.DataType[] {
    return source.sort((a, b) => {
      let sorted = 0;
      for (const prop in sortingFunc) {
        const dir = sorting[prop];
        const cmp = sortingFunc[prop];
        sorted = cmp(prop, a, b, dir);
        if (sorted) {
          break;
        }
      }
      return sorted;
    });
  }

  private getNextOrder(currentOrder: HbrTableNS.Order): HbrTableNS.Order {
    switch (currentOrder) {
      case undefined:
        return "asc";
      case "asc":
        return "desc";
      case "desc":
        return undefined;
    }
  }
}
