import { VNode, h } from "@stencil/core";

import { HbrTableNS } from "../../table-sub/interfaces";
import DataStore from "../../table-sub/store/dataSource/data.store";
import { SelectionStore } from "../../table-sub/store/selection/selection.store";
import ViewportStore from "../../table-sub/store/viewPort/viewport.store";
import { UUID } from "../../table-sub/utils/consts";
import { ViewportProps } from "../table/viewport.interfaces";
import { ElementScroll } from "../table/viewport.scrolling.service";
import { RowHeaderRender } from "./row-header-render";

type Props = {
	height: number;
	anyView: ViewportProps;
	resize: boolean;
	rowHeaderColumn?: HbrTableNS.RowHeaders;
	beforeRowAdd(y: number): SelectionStore;
	onScrollViewport(e: HbrTableNS.ViewPortScrollEvent): void;
	onElementToScroll(e: ElementScroll): void;
	tbSelf: any;
};

const LETTER_BLOCK_SIZE = 10;

const HbrgrRowHeaders = ({
	anyView,
	height,
	rowHeaderColumn,
	beforeRowAdd,
	onScrollViewport,
	onElementToScroll,
	tbSelf,
}: Props): VNode => {
	const dataViews: HTMLElement[] = [];
	const viewport = new ViewportStore();

	/** render viewports rows */
	let totalLength = 1;

	for (const data of anyView.dataPorts) {
		const colData = new DataStore<
			HbrTableNS.ColumnRegular,
			HbrTableNS.DimensionCols
		>("colPinStart");
		const rowSelectionStore = beforeRowAdd(data.position.y);

		const dataStore = new DataStore<
			HbrTableNS.DataType,
			HbrTableNS.DimensionRows
		>(data.type);
		dataStore.updateData(data.dataStore.get("source"));
		// initiate column data
		const column = {
			cellTemplate: RowHeaderRender(totalLength),
			...rowHeaderColumn,
		};
		colData.updateData([column]);
		dataViews.push(
			<hbr-table-data
				slot="content"
				{...data}
				dataStore={dataStore.store}
				colData={colData.store}
				viewportCol={viewport.store}
				readonly={true}
				range={false}
				rowSelectionStore={rowSelectionStore.store}
				tbSelf={tbSelf}
				role="rowgroup"
			/>,
		);
		totalLength += data.dataStore.get("items").length;
	}

	const colSize =
		rowHeaderColumn?.size ||
		(totalLength.toString().length + 1) * LETTER_BLOCK_SIZE;
	viewport.setViewport({
		realCount: 1,
		virtualSize: 0,
		items: [
			{
				size: colSize,
				start: 0,
				end: colSize,
				itemIndex: 0,
			},
		],
	});

	const parent = `${anyView.prop[UUID]}-rowHeaders`;
	return (
		<hbr-viewport-scroll
			{...{ [UUID]: parent }}
			contentHeight={height}
			contentWidth={0}
			class="rowHeaders"
			key="rowHeaders"
			style={{ minWidth: `${colSize}px` }}
			ref={(el) => onElementToScroll(el)}
			onScrollViewport={(e) => onScrollViewport(e.detail)}
		>
			<hbr-table-header
				{...{
					...anyView.headerProp,
					colData: typeof rowHeaderColumn === "object" ? [rowHeaderColumn] : [],
				}}
				viewportCol={viewport.store}
				parent={parent}
				slot="header"
				canResize={false}
				role="rowgroup"
			/>
			{dataViews}
		</hbr-viewport-scroll>
	);
};

export default HbrgrRowHeaders;
