import { reduce } from "../../utils/function-helper";
import { HbrTableNS } from "../interfaces";
import { columnTypes, rowTypes } from "../store/storeTypes";
import ViewportStore from "../store/viewPort/viewport.store";

export type ViewportStores = {
  [T in HbrTableNS.MultiDimensionType]: ViewportStore;
};
export default class ViewportProvider {
  readonly stores: ViewportStores;
  constructor() {
    this.stores = reduce(
      [...rowTypes, ...columnTypes],
      (sources: Partial<ViewportStores>, k: HbrTableNS.MultiDimensionType) => {
        sources[k] = new ViewportStore();
        return sources;
      },
      {}
    ) as ViewportStores;
  }

  setViewport(
    dimensionType: HbrTableNS.MultiDimensionType,
    data: Partial<HbrTableNS.ViewportState>
  ): void {
    this.stores[dimensionType].setViewport(data);
  }
}
