import { each } from "../../utils/function-helper";
import { HbrPlugin, HbrTableNS } from "../interfaces";
import { ColumnCollection } from "../services/column.data.provider";
import DimensionProvider, { ColumnItems } from "../services/dimension.provider";
import { getScrollbarWidth } from "../utils/utils";
import BasePlugin from "./basePlugin";

/**
 * This plugin serves to recalculate columns initially
 * Base on empty space if there is any
 * Currently plugin supports only increasing last column
 */
type ScrollChange = {
  type: HbrTableNS.DimensionType;
  hasScroll: boolean;
};
type StretchedData = {
  initialSize: number;
  size: number;
  index: number;
};
export default class StretchColumn extends BasePlugin {
  private stretchedColumn: StretchedData | null = null;
  private readonly scrollSize;
  name = "stretchColumn";
  constructor(
    hbrtable: HTMLHbrTableElement,
    private dimensionProvider: DimensionProvider
  ) {
    super(hbrtable);
    this.scrollSize = getScrollbarWidth(document);
    const beforecolumnapplied = ({
      detail: { columns },
    }: CustomEvent<ColumnCollection>) => {
      setTimeout(() => {
        this.applyStretch(columns);
      }, 100);
    };
    this.addEventListener("beforecolumnapplied", beforecolumnapplied);
  }

  private setScroll({ type, hasScroll }: ScrollChange) {
    if (
      type === "rgRow" &&
      this.stretchedColumn &&
      this.stretchedColumn?.initialSize === this.stretchedColumn.size
    ) {
      if (hasScroll) {
        this.stretchedColumn.size -= this.scrollSize;
        this.apply();
        this.dropChanges();
      }
    }
  }

  private activateChanges() {
    const setScroll = ({ detail }: CustomEvent<ScrollChange>) =>
      this.setScroll(detail);
    this.addEventListener("scrollchange", setScroll);
  }

  private dropChanges() {
    this.stretchedColumn = null;
    this.removeEventListener("scrollchange");
  }

  private apply() {
    if (!this.stretchedColumn) {
      return;
    }
    const type: HbrTableNS.DimensionCols = "rgCol";
    this.dimensionProvider.setDimensionSize(type, {
      [this.stretchedColumn.index]: this.stretchedColumn.size,
    });
  }

  applyStretch(columns: ColumnItems) {
    this.dropChanges();
    let sizeDifference = this.hbrtable.clientWidth - 1;
    each(columns, (_c, type: HbrTableNS.DimensionCols) => {
      const realSize =
        this.dimensionProvider.stores[type].store.get("realSize");
      sizeDifference -= realSize;
    });
    if (sizeDifference > 0) {
      // currently plugin accepts last column
      const index = columns.rgCol.length - 1;
      const last = columns.rgCol[index];
      // has column
      // no auto size applied
      // size for column shouldn't be defined
      const colSize = last?.size || this.hbrtable.colSize || 0;
      const size = sizeDifference + colSize - 1;
      if (last && !last.autoSize && colSize < size) {
        this.stretchedColumn = {
          initialSize: size,
          index,
          size,
        };
        this.apply();
        this.activateChanges();
      }
    }
  }
}

export function isStretchPlugin(
  plugin: HbrPlugin.Plugin | StretchColumn
): plugin is StretchColumn {
  return !!(plugin as StretchColumn).applyStretch;
}
