import { reduce } from "../../utils/function-helper";
import { HbrTableNS } from "../interfaces";
import { getItemByIndex } from "../store/dimension/dimension.helpers";
import DimensionStore from "../store/dimension/dimension.store";
import { columnTypes, rowTypes } from "../store/storeTypes";
import ViewportProvider from "./viewport.provider";

export type ColumnItems = Record<
  HbrTableNS.DimensionCols,
  HbrTableNS.ColumnRegular[]
>;

export type DimensionStores = {
  [T in HbrTableNS.MultiDimensionType]: DimensionStore;
};
export default class DimensionProvider {
  public readonly stores: DimensionStores;
  constructor(private viewports: ViewportProvider) {
    this.stores = reduce(
      [...rowTypes, ...columnTypes],
      (sources: Partial<DimensionStores>, k: HbrTableNS.MultiDimensionType) => {
        sources[k] = new DimensionStore();
        return sources;
      },
      {}
    ) as DimensionStores;
  }

  setDimensionSize(
    dimensionType: HbrTableNS.MultiDimensionType,
    sizes: HbrTableNS.ViewSettingSizeProp
  ): void {
    this.stores[dimensionType].setDimensionSize(sizes);
    this.viewports.stores[dimensionType].setViewPortDimension(sizes);
  }

  setRealSize(
    realCount: number,
    type: HbrTableNS.MultiDimensionType,
    tbSelf?: any
  ): void {
    this.viewports.stores[type].setViewport({ realCount });
    if (type === "rgRow") {
      // need pin col as well
      this.stores[type].setRealSize(realCount, tbSelf);
    } else {
      this.stores[type].setRealSize(realCount);
    }
  }

  /**
   * Sets dimension data and view port coordinate
   * @param items - data/column items
   * @param type - dimension type
   */
  setData(
    items: HbrTableNS.ColumnRegular[] | HbrTableNS.DataType[],
    type: HbrTableNS.MultiDimensionType,
    noVirtual = false,
    tbSelf?: any
  ) {
    this.setRealSize(items.length, type, tbSelf);
    if (noVirtual) {
      this.setNoVirtual(type);
    }
    this.setViewPortCoordinate({
      coordinate: this.viewports.stores[type].store.get("lastCoordinate"),
      type,
    });
  }

  private setNoVirtual(type: HbrTableNS.MultiDimensionType) {
    const dimension: HbrTableNS.DimensionSettingsState =
      this.stores[type].getCurrentState();
    this.viewports.stores[type].setViewport({
      virtualSize: dimension.realSize,
    });
  }

  drop() {
    for (const type of columnTypes) {
      this.stores[type].drop();
    }
  }

  setColumns(
    type: HbrTableNS.MultiDimensionType,
    sizes?: HbrTableNS.ViewSettingSizeProp,
    noVirtual = false
  ): void {
    this.stores[type].setDimensionSize(sizes);

    if (noVirtual) {
      this.setNoVirtual(type);
    }
    this.setViewPortCoordinate({
      coordinate: this.viewports.stores[type].store.get("lastCoordinate"),
      type,
    });
  }

  setViewPortCoordinate({
    coordinate,
    type,
  }: {
    coordinate: number;
    type: HbrTableNS.MultiDimensionType;
  }): void {
    const dimension: HbrTableNS.DimensionSettingsState =
      this.stores[type].getCurrentState();
    this.viewports.stores[type].setViewPortCoordinate(coordinate, dimension);
  }

  getViewPortPos(e: HbrTableNS.ViewPortScrollEvent): number {
    const dimension: HbrTableNS.DimensionSettingsState =
      this.stores[e.dimension].getCurrentState();
    const item = getItemByIndex(dimension, e.coordinate);

    return item.start;
  }

  setSettings(
    data: Partial<HbrTableNS.DimensionSettingsState>,
    dimensionType: HbrTableNS.DimensionType
  ): void {
    let stores: HbrTableNS.MultiDimensionType[] = [];
    switch (dimensionType) {
      case "rgCol":
        stores = columnTypes;
        break;
      case "rgRow":
        stores = rowTypes;
        break;
    }
    for (const s of stores) {
      this.stores[s].setStore(data);
    }
  }
}
