import {
	LogicFunction,
	LogicFunctionExtraParam,
	LogicFunctionParam,
} from "../../filter.types";

const lt: LogicFunction = (
	value: LogicFunctionParam,
	extra?: LogicFunctionExtraParam,
) => {
	let conditionValue: number;
	if (typeof value === "number") {
		conditionValue = parseFloat(extra?.toString());
		return value < conditionValue;
	}
	return false;
};

lt.extra = "input";
export default lt;
