import { h } from "@stencil/core";
import { HbrTableNS } from "../../interfaces";
import BasePlugin from "../basePlugin";
import { FILTER_PROP, isFilterBtn } from "./filter.button";
import { FilterItem } from "./filter.pop";
import {
	FilterType,
	filterEntities,
	filterNames,
	filterTypes,
} from "./filter.service";
import { LogicFunction } from "./filter.types";

type CustomFilter = {
	columnFilterType: string; // property defined in column filter: string/number/abstract/enum...etc
	name: string;
	func: LogicFunction;
};

/**
 * @typedef ColumnFilterConfig
 * @type {object}
 * @property {FilterCollection|undefined} collection - preserved filter data
 * @property {string[]|undefined} include - filters to be included, if defined everything else out of scope will be ignored
 * @property {Record<string, CustomFilter>|undefined} customFilters - hash map of {FilterType:CustomFilter}.
 * A way to define your own filter types per column
 */
export type ColumnFilterConfig = {
	collection?: FilterCollection;
	include?: string[];
	customFilters?: Record<string, CustomFilter>;
};
type HeaderEvent = CustomEvent<HbrTableNS.ColumnRegular>;
type FilterCollectionItem = {
	filter: LogicFunction;
	type: FilterType;
	value?: any;
};

export type FilterCollection = Record<
	HbrTableNS.ColumnProp,
	FilterCollectionItem
>;

export const FILTER_TRIMMED_TYPE = "filter";

export default class FilterPlugin extends BasePlugin {
	private pop: HTMLRevogrFilterPanelElement;
	private filterCollection: FilterCollection = {};
	private possibleFilters: Record<string, string[]> = { ...filterTypes };
	private possibleFilterNames: Record<string, string> = { ...filterNames };
	private possibleFilterEntities: Record<string, LogicFunction> = {
		...filterEntities,
	};
	// @ts-ignore
	private handleFilter: any;
	// @ts-ignore
	private handleClearFilter: any;
	// @ts-ignore
	private handleSearchTextChange: any;

	constructor(
		protected revogrid: HTMLHbrTableElement,
		uiid: string,
		config?: ColumnFilterConfig,
	) {
		super(revogrid);
		if (config) {
			this.initConfig(config);
		}
		const headerclick = (e: HeaderEvent) => this.headerclick(e);
		const aftersourceset = () => {
			if (this.revogrid.disableFiltering) {
				return;
			}
			if (Object.keys(this.filterCollection).length) {
				this.filterByProps(this.filterCollection);
			}
		};
		this.addEventListener("headerclick", headerclick);
		this.addEventListener("aftersourceset", aftersourceset);
		this.handleFilter = this.filterByProps.bind(this);
		this.handleClearFilter = this.onClearFilter.bind(this);
		this.handleSearchTextChange = this.onSeachTextChange.bind(this);

		this.revogrid.registerVNode([
			<revogr-filter-panel
				revogrid={this.revogrid}
				uuid={`filter-${uiid}`}
				filterNames={this.possibleFilterNames}
				filterEntities={this.possibleFilterEntities}
				onFilterChange={(e) => this.onFilterChange(e.detail)}
				ref={(e) => (this.pop = e)}
			/>,
		]);
	}

	private initConfig(config: ColumnFilterConfig) {
		if (config.collection) {
			this.filterCollection = { ...config.collection };
		}
		if (config.customFilters) {
			for (const cType in config.customFilters) {
				const cFilter = config.customFilters[cType];
				if (!this.possibleFilters[cFilter.columnFilterType]) {
					this.possibleFilters[cFilter.columnFilterType] = [];
				}
				this.possibleFilters[cFilter.columnFilterType].push(cType);
				this.possibleFilterEntities[cType] = cFilter.func;
				this.possibleFilterNames[cType] = cFilter.name;
			}
		}

		/**
		 * which filters has to be included/excluded
		 * convinient way to exclude system filters
		 */
		if (config.include) {
			const filters: Record<string, string[]> = {};

			for (const t in this.possibleFilters) {
				// validate filters, if appropriate function present
				const newTypes = this.possibleFilters[t].filter(
					(f) => config.include.indexOf(f) > -1,
				);
				if (newTypes.length) {
					filters[t] = newTypes;
				}
			}
			// if any valid filters provided show them
			if (Object.keys(filters).length > 0) {
				this.possibleFilters = filters;
			}
		}
	}

	private async headerclick(e: HeaderEvent) {
		const el = e.detail.originalEvent?.target as HTMLElement;
		if (!isFilterBtn(el)) {
			return;
		}
		e.preventDefault();

		// close if same
		const changes = await this.pop.getChanges();
		if (changes && changes?.prop === e.detail.prop) {
			this.pop.show();
			return;
		}

		// filter button clicked, open filter dialog
		const gridPos = this.revogrid.getBoundingClientRect();
		const buttonPos = el.getBoundingClientRect();
		const prop = e.detail.prop;
		this.pop.filterTypes = this.getColumnFilter(e.detail.filter);
		this.pop.show({
			...this.filterCollection[prop],
			x: buttonPos.x - gridPos.x,
			y: buttonPos.y - gridPos.y + buttonPos.height,
			prop,
		});
	}

	private getColumnFilter(
		type?: boolean | string | string[],
	): Record<string, string[]> {
		let filterType = "string";
		if (!type) {
			return { [filterType]: this.possibleFilters[filterType] };
		}

		// if custom column filter
		if (this.isValidType(type)) {
			filterType = type;

			// if multiple filters applied
		} else if (typeof type === "object" && type.length) {
			return type.reduce((r: Record<string, string[]>, multiType) => {
				if (this.isValidType(multiType)) {
					r[multiType] = this.possibleFilters[multiType];
				}
				return r;
			}, {});
		}
		return { [filterType]: this.possibleFilters[filterType] };
	}

	private isValidType(type: any): type is string {
		return !!(typeof type === "string" && this.possibleFilters[type]);
	}

	// called on internal component change
	private async onFilterChange(filterItem: FilterItem) {
		this.filterByProps({ [filterItem.prop]: filterItem });
	}

	/**
	 * clear all the filter
	 */
	private async onClearFilter() {
		const columns = await this.revogrid.getColumns();
		const filterItems = columns.reduce((cum, cur) => {
			cum[cur.prop] = {
				prop: cur.prop,
				type: "none",
				value: "",
			};
			return cum;
		}, {});
		// @ts-ignore
		await this.filterByProps(filterItems, true);
	}

	private async onSeachTextChange(value: string) {
		const source = await this.revogrid.getSource();
		const columns = await this.revogrid.getColumns();
		const { defaultPrevented: beforefilterapplyDefaultPrevented } = this.emit(
			"beforefilterapply",
			{
				collection: this.filterCollection,
				source,
				columns,
			},
		);
		if (beforefilterapplyDefaultPrevented) {
			return;
		}
		const searchFilter = await this.getSearchTextRowFilter(value);
		const columnFilter = await this.getAllColumnSearchFilter();
		const filter = {
			...searchFilter,
			...columnFilter,
		};
		// check is filter event prevented
		const { defaultPrevented } = this.emit("beforefiltertrimmed", {
			collection: this.filterCollection,
			itemsToFilter: filter,
			source,
		});
		if (defaultPrevented) {
			return;
		}
		// check is trimmed event prevented
		const isAddedEvent = await this.revogrid.addTrimmed(
			filter,
			FILTER_TRIMMED_TYPE,
		);
		if (isAddedEvent.defaultPrevented) {
			return;
		}
		this.emit("afterFilterApply", {
			collection: this.filterCollection,
			itemsToFilter: filter,
			source,
		});
	}

	/**
	 * get search text row filter
	 * @param value: search text
	 * @returns
	 */
	private async getSearchTextRowFilter(value: string) {
		const source = await this.revogrid.getSource();
		const columns = await this.revogrid.getColumns();
		const itemsToFilter = columns.reduce((con, cur) => {
			const condition = {
				[cur.prop]: {
					filter: this.possibleFilterEntities.contains,
					type: "contains",
					value,
				},
			};
			const rowFilter = this.getRowFilter(
				source,
				condition as FilterCollection,
			);
			Object.keys(rowFilter).forEach((r) => {
				if (!con.hasOwnProperty(r)) con[r] = 1;
				else con[r]++;
			});
			return con;
		}, {});
		Object.keys(itemsToFilter).forEach((i) => {
			if (itemsToFilter[i] !== columns.length) delete itemsToFilter[i];
		});
		return itemsToFilter;
	}

	/**
	 * get columns search filter
	 * @returns
	 */
	private async getAllColumnSearchFilter() {
		const columns = await this.revogrid.getColumns();
		const source = await this.revogrid.getSource();
		const columnsToUpdate: HbrTableNS.ColumnRegular[] = [];
		// todo improvement: loop through collection of props
		const collection = this.filterCollection;
		columns.forEach((rgCol) => {
			const column = { ...rgCol };
			const hasFilter = collection[column.prop];
			if (column[FILTER_PROP] && !hasFilter) {
				delete column[FILTER_PROP];
				columnsToUpdate.push(column);
			}
			if (!column[FILTER_PROP] && hasFilter) {
				columnsToUpdate.push(column);
				column[FILTER_PROP] = true;
			}
		});
		const itemsToFilter = this.getRowFilter(source, collection);
		return itemsToFilter;
	}

	/**
	 * Apply filters collection to extend existing one or override
	 * @method
	 * @param conditions - list of filters to apply
	 */
	async filterByProps(
		conditions: Record<HbrTableNS.ColumnProp, FilterItem>,
		override = false,
	) {
		if (override) {
			this.filterCollection = {};
		}
		for (const prop in conditions) {
			const { type, value } = conditions[prop];
			if (type === "none") {
				delete this.filterCollection[prop];
			} else {
				const filter = this.possibleFilterEntities[type];
				this.filterCollection[prop] = {
					filter,
					value,
					type,
				};
			}
		}
		const source = await this.revogrid.getSource();
		const columns = await this.revogrid.getColumns();
		const { defaultPrevented, detail } = this.emit("beforefilterapply", {
			collection: this.filterCollection,
			source,
			columns,
		});
		if (defaultPrevented) {
			return;
		}
		this.doFiltering(detail.collection, detail.source, detail.columns);
	}

	/**
	 * Triggers grid filtering
	 */
	async doFiltering(
		collection: FilterCollection,
		items: HbrTableNS.DataType[],
		columns: HbrTableNS.ColumnRegular[],
	) {
		const columnsToUpdate: HbrTableNS.ColumnRegular[] = [];
		// todo improvement: loop through collection of props
		columns.forEach((rgCol) => {
			const column = { ...rgCol };
			const hasFilter = collection[column.prop];
			if (column[FILTER_PROP] && !hasFilter) {
				delete column[FILTER_PROP];
				columnsToUpdate.push(column);
			}
			if (!column[FILTER_PROP] && hasFilter) {
				columnsToUpdate.push(column);
				column[FILTER_PROP] = true;
			}
		});
		let itemsToFilter = this.getRowFilter(items, collection);
		// @ts-ignore
		if (this.hbrtable.searchText) {
			// @ts-ignore
			const searchTextFilter = await this.getSearchTextRowFilter(
				this.hbrtable.searchText,
			);
			itemsToFilter = {
				...itemsToFilter,
				...searchTextFilter,
			};
		}
		// check is filter event prevented
		const { defaultPrevented, detail } = this.emit("beforefiltertrimmed", {
			collection,
			itemsToFilter,
			source: items,
		});
		if (defaultPrevented) {
			return;
		}
		// check is trimmed event prevented
		const isAddedEvent = await this.revogrid.addTrimmed(
			detail.itemsToFilter,
			FILTER_TRIMMED_TYPE,
		);
		if (isAddedEvent.defaultPrevented) {
			return;
		}
		await this.revogrid.updateColumns(columnsToUpdate);
		this.emit("afterFilterApply", { collection, itemsToFilter, source: items });
	}

	private getRowFilter(
		rows: HbrTableNS.DataType[],
		collection: FilterCollection,
	) {
		const trimmed: Record<number, boolean> = {};
		rows.forEach((model, rowIndex) => {
			for (const prop in collection) {
				const filterItem = collection[prop];
				const filter = filterItem.filter;
				if (!filter(model[prop], filterItem.value)) {
					trimmed[rowIndex] = true;
				}
			}
		});
		return trimmed;
	}
}
